import {
    useId, useRef, useState,
    type ComponentProps, type FormEvent, type KeyboardEvent, type ReactNode,
} from "react";
import { Button } from "./button";
import { Textarea } from "./textarea";
import { cn } from "./utils";

type PromptEnterBehavior = "enter" | "modifier-enter";
type PromptInputTextareaProps = Omit<ComponentProps<"textarea">,
    | "children" | "className" | "defaultValue" | "disabled" | "id"
    | "onChange" | "onKeyDown" | "placeholder" | "value"
>;

type PromptInputProps = {
    onSend: (text: string) => void | Promise<void>;
    value?: string;
    defaultValue?: string;
    onValueChange?: (value: string) => void;
    label?: string;
    placeholder?: string;
    disabled?: boolean;
    busy?: boolean;
    onStop?: () => void | Promise<void>;
    attachments?: ReactNode;
    context?: ReactNode;
    children?: ReactNode;
    textareaProps?: PromptInputTextareaProps;
    enterBehavior?: PromptEnterBehavior;
    sendErrorMessage?: string;
    className?: string;
};

function errorText(error: unknown, fallback: string) {
    return error instanceof Error && error.message.trim()
        ? error.message : fallback;
}

function PromptInput({
    onSend,
    value,
    defaultValue,
    onValueChange,
    label = "메시지",
    placeholder = "메시지를 입력하세요",
    disabled = false,
    busy = false,
    onStop,
    attachments,
    context,
    children,
    textareaProps,
    enterBehavior = "enter",
    sendErrorMessage = "메시지를 전달하지 못했습니다. 다시 시도하세요.",
    className,
}: PromptInputProps) {
    const inputId = useId();
    const controlled = value !== undefined;
    const [internalValue, setInternalValue] = useState(defaultValue ?? "");
    const text = controlled ? value : internalValue;
    const latestText = useRef(text);
    latestText.current = text;
    const sendPending = useRef(false);
    const stopPending = useRef(false);
    const [sending, setSending] = useState(false);
    const [stopping, setStopping] = useState(false);
    const [error, setError] = useState<string | null>(null);

    if (enterBehavior !== "enter" && enterBehavior !== "modifier-enter") {
        throw new RangeError("PromptInput enterBehavior is not supported.");
    }

    function updateText(next: string) {
        if (!controlled) setInternalValue(next);
        onValueChange?.(next);
        setError(null);
    }

    async function submit(event: FormEvent<HTMLFormElement>) {
        event.preventDefault();
        const submittedText = text.trim();
        if (!submittedText || disabled || busy || sendPending.current) return;

        sendPending.current = true;
        setSending(true);
        setError(null);
        try {
            await onSend(submittedText);
            if (latestText.current === text) updateText("");
        } catch (reason) {
            setError(errorText(reason, sendErrorMessage));
        } finally {
            sendPending.current = false;
            setSending(false);
        }
    }

    async function stop() {
        if (!onStop || disabled || !busy || stopPending.current) return;
        stopPending.current = true;
        setStopping(true);
        setError(null);
        try {
            await onStop();
        } catch (reason) {
            setError(errorText(reason, sendErrorMessage));
        } finally {
            stopPending.current = false;
            setStopping(false);
        }
    }

    function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
        if (event.key !== "Enter" || event.shiftKey ||
            event.nativeEvent.isComposing || event.nativeEvent.keyCode === 229) {
            return;
        }
        const shouldSubmit = enterBehavior === "enter" ||
            event.ctrlKey || event.metaKey;
        if (!shouldSubmit) return;
        event.preventDefault();
        event.currentTarget.form?.requestSubmit();
    }

    return (
        <form
            onSubmit={(event) => void submit(event)}
            data-ui="prompt-input"
            aria-busy={busy || sending || stopping}
            className={cn(
                "flex min-w-0 flex-col gap-2 rounded-sm border border-border " +
                "bg-surface p-[var(--space-3)]",
                className,
            )}
        >
            <label className="sr-only" htmlFor={inputId}>{label}</label>
            {context != null && (
                <div data-slot="composer-context">{context}</div>
            )}
            {attachments != null && (
                <div data-slot="composer-attachments">{attachments}</div>
            )}
            <Textarea
                {...textareaProps}
                id={inputId}
                value={text}
                onChange={(event) => updateText(event.target.value)}
                onKeyDown={handleKeyDown}
                placeholder={placeholder}
                disabled={disabled}
                rows={textareaProps?.rows ?? 2}
                data-slot="composer-control"
            />
            {error && <p role="alert" className="m-0 text-sm text-danger">
                {error}
            </p>}
            <div className="flex flex-wrap items-center justify-end gap-2"
                data-slot="composer-actions">
                {children}
                {busy ? onStop ? (
                    <Button type="button" variant="outline"
                        disabled={disabled || stopping}
                        onClick={() => void stop()}>
                        {stopping ? "중지 중…" : "중지"}
                    </Button>
                ) : (
                    <Button type="submit" disabled>
                        실행 중…
                    </Button>
                ) : (
                    <Button type="submit"
                        disabled={disabled || sending || !text.trim()}>
                        {sending ? "전송 중…" : "보내기"}
                    </Button>
                )}
            </div>
        </form>
    );
}

export { PromptInput };
export type {
    PromptEnterBehavior, PromptInputProps, PromptInputTextareaProps,
};
